    function specialCumulativeLevel(optionId, stars, localLevel) {
        var unlock = SPECIAL_UNLOCK_STAR[Number(optionId)] || 1;
        var selectedStars = Math.max(1, Math.min(5, Number(stars) || 1));
        var grade = selectedStars === 5 ? 4 : selectedStars;
        var level = selectedStars === 5
            ? 20
            : Math.max(0, Number(localLevel) || 0);
        var total = 0;
        var g;

        if (grade < unlock) { return 0; }

        for (g = unlock; g < grade; g += 1) {
            total += SPECIAL_STAR_LEVEL_CAP[g] || 0;
        }

        total += Math.min(level, SPECIAL_STAR_LEVEL_CAP[grade] || 0);
        return total;
    }

