        function updateWeaponVisualState(ui) {
            var record = currentWeaponRecord(ui);
            var heroName = activeHero ? activeHero.value : '';
            var heroInfo = HERO_INFO[heroName];
            var className = record ? record.className : '';
            var qualityName = ui.quality.value || '';
            var trackName = ui.track.value || 'Standard';
            var skillLabel = record && record.skillName
                ? record.skillName
                : (record ? 'No dedicated weapon skill at this quality' : 'Choose Track → Quality → Weapon.');
            var masteryMatch = !!(record && heroInfo && className && heroInfo.mastery === className);
            var maxLevel = ui.level.max || '';
            var levelText = ui.level.value
                ? 'Lv. ' + ui.level.value + (maxLevel ? ' / ' + maxLevel : '')
                : (maxLevel ? 'Lv. 1–' + maxLevel : 'Choose level');
            var frameClass = 'xpcalc-weapon-v08';
            var qualityToken = cssToken(qualityName);
            var trackToken = cssToken(trackName);
            var classToken = cssToken(className);

            if (ui.slot === 0) {
                frameClass += ' is-main';
            }
            if (record) {
                frameClass += ' has-weapon';
            }
            if (qualityToken) {
                frameClass += ' quality-' + qualityToken;
            }
            if (trackToken) {
                frameClass += ' track-' + trackToken;
            }
            if (classToken) {
                frameClass += ' class-' + classToken;
            }
            if (ui.slot === 0 && record) {
                frameClass += masteryMatch ? ' mastery-active' : ' mastery-inactive';
            }
            ui.wrap.className = frameClass;

            ui.identityName.textContent = record ? record.name : (ui.slot === 0 ? 'Main Weapon Slot' : 'Sub Weapon Slot');

            if (record) {
                ui.identityGlyphFallback.hidden = true;

                ui.weaponSprite.hidden = false;
                ui.weaponSprite.src = weaponSpriteUrl(record);
                ui.weaponSprite.alt = record.name + ' ' + record.quality;

                if (weaponClassIconUrl(className)) {
                    ui.classBadge.hidden = false;
                    ui.classBadgeImage.src = weaponClassIconUrl(className);
                    ui.classBadgeImage.alt = className + ' weapon type';
                } else {
                    ui.classBadge.hidden = true;
                    ui.classBadgeImage.removeAttribute('src');
                }

                ui.identityGlyph.title = record.name + ' — ' + className;
            } else {
                ui.weaponSprite.hidden = true;
                ui.weaponSprite.removeAttribute('src');
                ui.weaponSprite.alt = '';
                ui.classBadge.hidden = true;
                ui.classBadgeImage.removeAttribute('src');
                ui.identityGlyphFallback.hidden = false;
                ui.identityGlyphFallback.textContent = String(ui.slot + 1);
                ui.identityGlyph.title = 'Weapon slot';
            }

            setChipText(ui.trackChip, trackName === 'Standard' ? 'Regular' : trackName);
            setChipText(ui.qualityChip, qualityName || 'Quality');
            setChipText(ui.classChip, className || 'Type');
            ui.levelChip.textContent = levelText;
            ui.levelChip.classList.toggle('is-empty', !ui.level.value);
            ui.skillText.textContent = skillLabel;

            if (ui.slot === 0) {
                if (record && heroInfo) {
                    ui.statusText.textContent = masteryMatch
                        ? 'Mastery active for ' + heroInfo.mastery
                        : 'Mastery inactive — active hero uses ' + heroInfo.mastery;
                    ui.statusText.classList.toggle('is-active', masteryMatch);
                    ui.statusText.classList.toggle('is-inactive', !masteryMatch);
                } else {
                    ui.statusText.textContent = 'Select your main weapon to load mastery status.';
                    ui.statusText.classList.remove('is-active');
                    ui.statusText.classList.add('is-inactive');
                }
            } else {
                ui.statusText.textContent = record
                    ? (className + ' weapon • contributes to total loadout power')
                    : 'Optional sub-weapon slot';
                ui.statusText.classList.remove('is-active');
                ui.statusText.classList.toggle('is-inactive', !record);
            }
        }

