        function createSynergyIcon(key, className) {
            var wrap = el('span', className || 'xpcalc-synergy-icon');
            var img;

            wrap.setAttribute('aria-hidden', 'true');

            if (!key || !TRAIT_SYNERGY_ICONS[key]) {
                wrap.classList.add('is-empty');
                return wrap;
            }

            img = document.createElement('img');
            img.src =
                '/wiki/Special:Redirect/file/' +
                encodeURIComponent(TRAIT_SYNERGY_ICONS[key]);
            img.alt = '';
            img.loading = 'lazy';
            img.decoding = 'async';
            wrap.appendChild(img);

            return wrap;
        }

        function createSynergyVisualDropdown(select) {
            var wrap = el('div', 'xpcalc-synergy-visual-dropdown');
            var trigger = el('button', 'xpcalc-synergy-dropdown-trigger');
            var selectedVisual = el('span', 'xpcalc-synergy-selected-visual');
            var selectedLabel = el('span', 'xpcalc-synergy-selected-label', 'No synergy');
            var chevron = el('span', 'xpcalc-synergy-dropdown-chevron', '⌄');
            var menu = el('div', 'xpcalc-synergy-dropdown-menu');
            var choices = [];
            var options = orderedSelectOptions(synergyOptions(), false);
            var menuId;

            collapsibleCardId += 1;
            menuId = 'xpcalc-synergy-menu-' + collapsibleCardId;

            trigger.type = 'button';
            trigger.setAttribute('aria-haspopup', 'menu');
            trigger.setAttribute('aria-expanded', 'false');
            trigger.setAttribute('aria-controls', menuId);

            selectedVisual.appendChild(
                createSynergyIcon(
                    '',
                    'xpcalc-synergy-icon xpcalc-synergy-dropdown-selected-icon'
                )
            );
            trigger.appendChild(selectedVisual);
            trigger.appendChild(selectedLabel);
            chevron.setAttribute('aria-hidden', 'true');
            trigger.appendChild(chevron);

            menu.id = menuId;
            menu.setAttribute('role', 'menu');
            menu.hidden = true;

            function closeMenu(returnFocus) {
                menu.hidden = true;
                wrap.classList.remove('is-open');
                trigger.setAttribute('aria-expanded', 'false');

                if (returnFocus) {
                    trigger.focus();
                }
            }

            function focusChoice(index) {
                if (!choices.length) {
                    return;
                }

                if (index < 0) {
                    index = choices.length - 1;
                }

                if (index >= choices.length) {
                    index = 0;
                }

                choices[index].focus();
            }

            function openMenu(focusSelected) {
                var selectedIndex = 0;
                var i;

                menu.hidden = false;
                wrap.classList.add('is-open');
                trigger.setAttribute('aria-expanded', 'true');

                if (focusSelected) {
                    for (i = 0; i < choices.length; i += 1) {
                        if (choices[i].getAttribute('aria-checked') === 'true') {
                            selectedIndex = i;
                            break;
                        }
                    }
                    focusChoice(selectedIndex);
                }
            }

            function sync() {
                var key = select.value;
                var label = key && TRAIT_SYNERGIES[key]
                    ? TRAIT_SYNERGIES[key].label
                    : 'No synergy';
                var oldIcon = selectedVisual.querySelector('.xpcalc-synergy-dropdown-selected-icon');
                var newIcon = createSynergyIcon(
                    key,
                    'xpcalc-synergy-icon xpcalc-synergy-dropdown-selected-icon'
                );

                if (oldIcon) {
                    selectedVisual.replaceChild(newIcon, oldIcon);
                } else {
                    selectedVisual.appendChild(newIcon);
                }

                selectedLabel.textContent = label;

                choices.forEach(function (choice) {
                    var isSelected =
                        choice.getAttribute('data-value') === key;

                    choice.setAttribute(
                        'aria-checked',
                        isSelected ? 'true' : 'false'
                    );
                    choice.classList.toggle('is-selected', isSelected);
                });
            }

            options.forEach(function (option) {
                var key = option[0];
                var label = option[1];
                var choice = el('button', 'xpcalc-synergy-dropdown-option');
                var choiceIcon = createSynergyIcon(
                    key,
                    'xpcalc-synergy-icon xpcalc-synergy-dropdown-option-icon'
                );
                var choiceLabel = el(
                    'span',
                    'xpcalc-synergy-dropdown-option-label',
                    label
                );
                var check = el(
                    'span',
                    'xpcalc-synergy-dropdown-check',
                    '✓'
                );

                choice.type = 'button';
                choice.setAttribute('role', 'menuitemradio');
                choice.setAttribute('aria-checked', 'false');
                choice.setAttribute('data-value', key);

                check.setAttribute('aria-hidden', 'true');

                choice.appendChild(choiceIcon);
                choice.appendChild(choiceLabel);
                choice.appendChild(check);

                choice.addEventListener('click', function () {
                    select.value = key;
                    select.dispatchEvent(
                        new Event('change', { bubbles: true })
                    );
                    closeMenu(true);
                });

                choice.addEventListener('keydown', function (event) {
                    var index = choices.indexOf(choice);

                    if (event.key === 'ArrowDown') {
                        event.preventDefault();
                        focusChoice(index + 1);
                    } else if (event.key === 'ArrowUp') {
                        event.preventDefault();
                        focusChoice(index - 1);
                    } else if (event.key === 'Home') {
                        event.preventDefault();
                        focusChoice(0);
                    } else if (event.key === 'End') {
                        event.preventDefault();
                        focusChoice(choices.length - 1);
                    } else if (event.key === 'Escape') {
                        event.preventDefault();
                        closeMenu(true);
                    }
                });

                choices.push(choice);
                menu.appendChild(choice);
            });

            trigger.addEventListener('click', function () {
                if (menu.hidden) {
                    openMenu(false);
                } else {
                    closeMenu(false);
                }
            });

            trigger.addEventListener('keydown', function (event) {
                if (
                    event.key === 'ArrowDown' ||
                    event.key === 'ArrowUp'
                ) {
                    event.preventDefault();
                    openMenu(true);
                } else if (event.key === 'Escape' && !menu.hidden) {
                    event.preventDefault();
                    closeMenu(false);
                }
            });

            wrap.addEventListener('focusout', function () {
                window.setTimeout(function () {
                    if (!wrap.contains(document.activeElement)) {
                        closeMenu(false);
                    }
                }, 0);
            });

            select.classList.add('xpcalc-native-synergy-select');
            select.setAttribute('aria-hidden', 'true');
            select.tabIndex = -1;

            wrap.appendChild(select);
            wrap.appendChild(trigger);
            wrap.appendChild(menu);

            sync();

            return {
                wrap: wrap,
                trigger: trigger,
                menu: menu,
                sync: sync,
                close: closeMenu
            };
        }

