        /* CALCULATION SOURCE HELPERS */
        function readHeroCollection(activeHeroName) {
            var states = [];

            HERO_COLLECTION_ORDER.forEach(function (heroName) {
                var ui = rosterUi[heroName];
                var owned;
                var state;

                if (!ui) {
                    return;
                }

                owned = ui.owned.checked;

                if (!owned) {
                    return;
                }

                state = {
                    name: heroName,
                    owned: true,
                    level: clamp(
                        Math.trunc(numberValue(ui.level, 1)),
                        1,
                        130
                    ),
                    stars: clamp(
                        Math.trunc(numberValue(ui.stars, 0)),
                        0,
                        6
                    ),
                    qualityId: Number(
                        ui.quality.value ||
                        DATA.heroInitialQuality[heroName] ||
                        1
                    )
                };

                states.push(state);
            });

            return states;
        }

        function readWeapon(ui) {
            var record = currentWeaponRecord(ui);
            var optionStates = [];

            ui.options.forEach(function (option) {
                optionStates.push({
                    stat: option.stat.value,
                    value: numberValue(option.value, 0)
                });
            });

            return {
                slot: ui.slot,
                name: ui.name.value,
                track: ui.track.value,
                quality: ui.quality.value,
                level: Math.trunc(numberValue(ui.level, 0)),
                className: record ? record.className : '',
                rangeType: record ? record.rangeType : '',
                bonusGroup: record ? record.bonusGroup : '',
                skillName: record ? record.skillName : '',
                hasSkill: record ? Boolean(record.hasSkill) : false,
                powerSkill: record ? record.powerSkill : null,
                options: optionStates
            };
        }


