        var comparisonPlannedResult = null;
        var comparisonPlannedDirty = false;
        var comparisonHelpOverlay = null;
        var comparisonHelpPrimaryButton = null;
        var comparisonHelpSecondaryButton = null;
        var comparisonHelpCheckbox = null;
        var comparisonHelpPendingStart = false;
        var COMPARISON_HELP_STORAGE_KEY = 'xpHeroCalculatorCompareHelp_v1:' + pageName;

        function comparisonHelpShouldShow() {
            try {
                return window.localStorage.getItem(COMPARISON_HELP_STORAGE_KEY) !== 'hide';
            } catch (error) {
                return true;
            }
        }

        function comparisonHelpRememberPreference() {
            try {
                if (comparisonHelpCheckbox && comparisonHelpCheckbox.checked) {
                    window.localStorage.setItem(COMPARISON_HELP_STORAGE_KEY, 'hide');
                } else {
                    window.localStorage.removeItem(COMPARISON_HELP_STORAGE_KEY);
                }
            } catch (error) {
                /* localStorage may be unavailable; fail safely */
            }
        }

        function cloneComparisonData(value) {
            if (value === null || value === undefined) { return value; }
            try { return JSON.parse(JSON.stringify(value)); }
            catch (error) { return value; }
        }

        function comparisonFieldMap(build) {
            return build ? buildStateFieldMap(build) : {};
        }

        function comparisonFieldValue(map, key, fallback) {
            return map[key] ? map[key].value : fallback;
        }

        function comparisonQualityName(value) {
            var text = String(value === undefined || value === null ? '' : value);
            return DATA.qualities[text] || text || '—';
        }

        function comparisonTraitLabel(value) {
            return value && TRAIT_DEFS[value] ? TRAIT_DEFS[value].label : (value || 'None');
        }

        function comparisonSynergyLabel(value) {
            return value && TRAIT_SYNERGIES[value] ? TRAIT_SYNERGIES[value].label : (value || 'None');
        }

        function comparisonUpgradeName(group, id) {
            var sources = {
                ability: DATA.abilityNames || {},
                soul: DATA.soulNames || {},
                special: DATA.specialNames || {},
                extra: DATA.extraNames || {}
            };
            return sources[group] && sources[group][id] ? sources[group][id] : ('Upgrade ' + id);
        }

        function comparisonWeaponDescription(map, slot) {
            var name = comparisonFieldValue(map, 'weapon.' + slot + '.name', '');
            var quality = comparisonFieldValue(map, 'weapon.' + slot + '.quality', '');
            var level = comparisonFieldValue(map, 'weapon.' + slot + '.level', '');
            if (!name) { return 'Empty'; }
            return name + (quality ? ' · ' + quality : '') + (level ? ' · Lv.' + level : '');
        }

        function comparisonTraitDescription(map, slot) {
            var trait = comparisonFieldValue(map, 'trait.' + slot + '.trait', '');
            var grade = comparisonFieldValue(map, 'trait.' + slot + '.grade', '');
            var synergy = comparisonFieldValue(map, 'trait.' + slot + '.synergy', '');
            if (!trait && !grade && !synergy) { return 'Empty'; }
            return comparisonTraitLabel(trait) +
                (grade ? ' · ' + grade : '') +
                (synergy ? ' · ' + comparisonSynergyLabel(synergy) : '');
        }

        function comparisonBuildChanges(currentBuild, plannedBuild) {
            var currentMap = comparisonFieldMap(currentBuild);
            var plannedMap = comparisonFieldMap(plannedBuild);
            var changes = [];
            var oldValue;
            var newValue;
            var slot;
            var option;
            var group;
            var id;
            var key;
            var heroName;
            var activeHeroNames = [];

            function push(title, detail) {
                changes.push({ title: title, detail: detail });
            }

            oldValue = comparisonFieldValue(currentMap, 'player.level', '');
            newValue = comparisonFieldValue(plannedMap, 'player.level', '');
            if (String(oldValue) !== String(newValue)) {
                push('Player Level', oldValue + ' → ' + newValue);
            }

            oldValue = comparisonFieldValue(currentMap, 'player.activeHero', '');
            newValue = comparisonFieldValue(plannedMap, 'player.activeHero', '');
            if (String(oldValue) !== String(newValue)) {
                push('Active Hero', (oldValue || 'None') + ' → ' + (newValue || 'None'));
            }
            if (oldValue) { activeHeroNames.push(oldValue); }
            if (newValue && activeHeroNames.indexOf(newValue) === -1) { activeHeroNames.push(newValue); }

            activeHeroNames.forEach(function (name) {
                ['level', 'stars', 'quality'].forEach(function (field) {
                    var fieldKey = 'hero.' + name + '.' + field;
                    var before = comparisonFieldValue(currentMap, fieldKey, '');
                    var after = comparisonFieldValue(plannedMap, fieldKey, '');
                    if (String(before) === String(after)) { return; }
                    if (field === 'quality') {
                        push(name + ' Quality', comparisonQualityName(before) + ' → ' + comparisonQualityName(after));
                    } else if (field === 'stars') {
                        push(name + ' Stars', before + '★ → ' + after + '★');
                    } else {
                        push(name + ' Level', 'Lv.' + before + ' → Lv.' + after);
                    }
                });
            });

            for (slot = 1; slot <= 6; slot += 1) {
                var weaponFieldsChanged = ['name', 'quality', 'level', 'track'].some(function (field) {
                    var fieldKey = 'weapon.' + slot + '.' + field;
                    return String(comparisonFieldValue(currentMap, fieldKey, '')) !==
                        String(comparisonFieldValue(plannedMap, fieldKey, ''));
                });
                if (weaponFieldsChanged) {
                    push(
                        slot === 1 ? 'Main Weapon' : 'Weapon Slot ' + slot,
                        comparisonWeaponDescription(currentMap, slot) + ' → ' +
                        comparisonWeaponDescription(plannedMap, slot)
                    );
                }

                for (option = 1; option <= 3; option += 1) {
                    var statKey = 'weapon.' + slot + '.option.' + option + '.stat';
                    var valueKey = 'weapon.' + slot + '.option.' + option + '.value';
                    var beforeStat = comparisonFieldValue(currentMap, statKey, '');
                    var afterStat = comparisonFieldValue(plannedMap, statKey, '');
                    var beforeVal = comparisonFieldValue(currentMap, valueKey, '');
                    var afterVal = comparisonFieldValue(plannedMap, valueKey, '');
                    if (String(beforeStat) === String(afterStat) && String(beforeVal) === String(afterVal)) {
                        continue;
                    }
                    push(
                        (slot === 1 ? 'Main Weapon' : 'Weapon ' + slot) + ' · Option ' + option,
                        (beforeStat ? shareWeaponOptionLabel(beforeStat) + ' +' + beforeVal : 'None') +
                        ' → ' +
                        (afterStat ? shareWeaponOptionLabel(afterStat) + ' +' + afterVal : 'None')
                    );
                }
            }

            for (slot = 1; slot <= 5; slot += 1) {
                var traitChanged = ['trait', 'grade', 'synergy'].some(function (field) {
                    var fieldKey = 'trait.' + slot + '.' + field;
                    return String(comparisonFieldValue(currentMap, fieldKey, '')) !==
                        String(comparisonFieldValue(plannedMap, fieldKey, ''));
                });
                if (traitChanged) {
                    push(
                        'Trait ' + slot,
                        comparisonTraitDescription(currentMap, slot) + ' → ' +
                        comparisonTraitDescription(plannedMap, slot)
                    );
                }
            }

            ['ability', 'soul', 'special', 'extra'].forEach(function (groupName) {
                var prefix = 'upgrade.' + groupName + '.';
                Object.keys(plannedMap).forEach(function (fieldKey) {
                    if (fieldKey.indexOf(prefix) !== 0 || fieldKey.slice(-6) !== '.level') { return; }
                    var parts = fieldKey.split('.');
                    var upgradeId = parts[2];
                    var before = comparisonFieldValue(currentMap, fieldKey, '0');
                    var after = comparisonFieldValue(plannedMap, fieldKey, '0');
                    if (String(before) === String(after)) { return; }
                    push(
                        comparisonUpgradeName(groupName, upgradeId),
                        'Lv.' + (before || 0) + ' → Lv.' + (after || 0)
                    );
                });
            });

            oldValue = comparisonFieldValue(currentMap, 'upgrade.special.stars', '');
            newValue = comparisonFieldValue(plannedMap, 'upgrade.special.stars', '');
            if (String(oldValue) !== String(newValue)) {
                push('Special Promotion', (oldValue || 1) + '★ → ' + (newValue || 1) + '★');
            }

            return changes;
        }

        function comparisonMetricValue(state, key) {
            if (!state) { return null; }
            if (key === 'cooldownRate') {
                return state.stats ? Number(state.stats.cooldownRate || 0) : 0;
            }
            return Number(state[key] || 0);
        }

        function comparisonFormatMetric(key, value) {
            if (value === null || value === undefined || !isFinite(value)) { return '—'; }
            if (key === 'vampRate' || key === 'cooldownRate') {
                return formatRatio(value, 1);
            }
            return formatMetric(value);
        }

        function comparisonDeltaText(key, currentValue, plannedValue) {
            var delta;
            var relative;
            var sign;
            if (currentValue === null || plannedValue === null) { return 'Recalculate Planned'; }
            delta = plannedValue - currentValue;
            if (Math.abs(delta) < 1e-12) { return 'No change'; }
            sign = delta > 0 ? '+' : '−';
            if (key === 'vampRate' || key === 'cooldownRate') {
                return sign + trimZeros((Math.abs(delta) * 100).toFixed(1)) + ' pts';
            }
            relative = currentValue !== 0 ? (delta / Math.abs(currentValue)) * 100 : null;
            return sign + formatMetric(Math.abs(delta)) +
                (relative === null ? '' : ' · ' + sign + trimZeros(Math.abs(relative).toFixed(1)) + '%');
        }

        function renderComparisonChanges() {
            var changes;
            var plannedBuild;
            var maxVisible = 10;
            comparisonChangesList.textContent = '';

            if (!buildComparisonMode || !comparisonCurrentBuild) {
                return;
            }

            plannedBuild = captureBuildState(root);
            changes = comparisonBuildChanges(comparisonCurrentBuild, plannedBuild);

            if (!changes.length) {
                comparisonChangesList.appendChild(
                    el('div', 'xpcalc-compare-change-empty', 'Planned currently matches Current.')
                );
                return;
            }

            changes.slice(0, maxVisible).forEach(function (change) {
                var item = el('div', 'xpcalc-compare-change');
                item.appendChild(el('div', 'xpcalc-compare-change-title', change.title));
                item.appendChild(el('div', 'xpcalc-compare-change-detail', change.detail));
                comparisonChangesList.appendChild(item);
            });

            if (changes.length > maxVisible) {
                comparisonChangesList.appendChild(
                    el('div', 'xpcalc-compare-change-more', '+' + (changes.length - maxVisible) + ' more build changes')
                );
            }
        }

        function updateComparisonUi() {
            var keys = ['totalPower', 'power', 'maxHp', 'hpRegen', 'vampRate', 'cooldownRate'];
            var currentHero;
            var plannedHero;

            if (!buildComparisonMode || !comparisonCurrentResult) {
                comparisonCard.card.hidden = true;
                comparisonBar.hidden = true;
                return;
            }

            comparisonCard.card.hidden = false;
            comparisonBar.hidden = false;
            currentHero = comparisonCurrentResult.hero || {};
            plannedHero = comparisonPlannedResult && comparisonPlannedResult.hero
                ? comparisonPlannedResult.hero
                : null;

            comparisonHeroLine.textContent =
                'CURRENT · ' + (currentHero.name || 'Build') + ' · ' + (currentHero.quality || '') +
                ' · Lv.' + (currentHero.level || '—') +
                '   →   PLANNED · ' +
                (plannedHero ? (plannedHero.name + ' · ' + plannedHero.quality + ' · Lv.' + plannedHero.level) : 'Recalculate after your changes');

            keys.forEach(function (key) {
                var nodes = comparisonMetricNodes[key];
                var currentValue = comparisonMetricValue(comparisonCurrentResult, key);
                var plannedValue = comparisonPlannedResult
                    ? comparisonMetricValue(comparisonPlannedResult, key)
                    : null;
                var delta = plannedValue === null ? null : plannedValue - currentValue;
                nodes.current.textContent = comparisonFormatMetric(key, currentValue);
                nodes.planned.textContent = comparisonFormatMetric(key, plannedValue);
                nodes.delta.textContent = comparisonDeltaText(key, currentValue, plannedValue);
                nodes.delta.className = 'xpcalc-compare-delta' +
                    (delta === null || Math.abs(delta) < 1e-12 ? '' : (delta > 0 ? ' is-positive' : ' is-negative'));
            });

            if (comparisonPlannedResult) {
                var currentPower = comparisonMetricValue(comparisonCurrentResult, 'totalPower');
                var plannedPower = comparisonMetricValue(comparisonPlannedResult, 'totalPower');
                comparisonBarText.textContent =
                    'Current ' + formatMetric(currentPower) + ' → Planned ' + formatMetric(plannedPower) +
                    ' · ' + comparisonDeltaText('totalPower', currentPower, plannedPower);
                comparisonUsePlanned.disabled = false;
            } else {
                comparisonBarText.textContent =
                    'Current ' + formatMetric(comparisonMetricValue(comparisonCurrentResult, 'totalPower')) +
                    ' · Planned build changed — press Recalculate to update the comparison.';
                comparisonUsePlanned.disabled = true;
            }

            renderComparisonChanges();
        }

        function markComparisonDirty() {
            if (!buildComparisonMode || buildRestoreInProgress) { return; }
            comparisonPlannedDirty = true;
            comparisonPlannedResult = null;
            setBuildPersistenceStatus('Autosave: Paused · Comparing');
            updateComparisonUi();
        }

        function handleSuccessfulComparisonCalculation(state) {
            if (!buildComparisonMode) {
                compare.disabled = false;
                compare.textContent = 'Compare Builds';
                compare.title = 'Snapshot this calculated build as Current and create an editable Planned build.';
                return;
            }
            comparisonPlannedResult = cloneComparisonData(state);
            comparisonPlannedDirty = false;
            compare.disabled = true;
            compare.textContent = 'Comparing';
            setBuildPersistenceStatus('Autosave: Paused · Comparing');
            updateComparisonUi();
        }

        function ensureComparisonHelpModal() {
            if (comparisonHelpOverlay) {
                return comparisonHelpOverlay;
            }

            var overlay = el('div', 'xpcalc-compare-help-overlay');
            var dialog = el('div', 'xpcalc-compare-help-dialog');
            var eyebrow = el('div', 'xpcalc-compare-help-eyebrow', 'BUILD PLANNING TOOL');
            var title = el('div', 'xpcalc-compare-help-title', 'COMPARE BUILDS');
            var copy = el('div', 'xpcalc-compare-help-copy',
                'Test upgrades and loadout changes without risking the build you already saved.');
            var steps = el('div', 'xpcalc-compare-help-steps');
            var note = el('div', 'xpcalc-compare-help-note');
            var noteTitle = el('div', 'xpcalc-compare-help-note-title', 'YOUR CURRENT BUILD IS SAFE');
            var noteCopy = el('div', 'xpcalc-compare-help-note-copy',
                'Autosave pauses while Compare is active. Nothing replaces your normal saved build unless you choose Use Planned.');
            var toggleWrap = el('label', 'xpcalc-compare-help-toggle');
            var checkbox = createInput('checkbox', '', null, null, null);
            var customCheck = el('span', 'xpcalc-compare-help-checkmark');
            var toggleText = el('span', 'xpcalc-compare-help-toggle-text', "Don't show this automatically again");
            var controls = el('div', 'xpcalc-compare-help-actions');
            var primary = createButton('Start Comparison', false, false);
            var secondary = createButton('Cancel', false, false);

            [
                {
                    number: '1',
                    title: 'Current becomes your baseline',
                    detail: 'The build you just calculated is protected as CURRENT.'
                },
                {
                    number: '2',
                    title: 'Edit the Planned build',
                    detail: 'Use the normal calculator controls to test weapons, traits, levels, upgrades, or hero changes.'
                },
                {
                    number: '3',
                    title: 'Press Recalculate',
                    detail: 'The calculator updates PLANNED and shows exactly how its results differ from Current.'
                },
                {
                    number: '4',
                    title: 'Review the comparison',
                    detail: 'Check Current vs Planned stat deltas and the What Changed? breakdown.'
                },
                {
                    number: '5',
                    title: 'Choose what happens next',
                    detail: 'Use Planned keeps the experiment. Reset Planned starts over. Exit restores Current.'
                }
            ].forEach(function (step) {
                var row = el('div', 'xpcalc-compare-help-step');
                var number = el('div', 'xpcalc-compare-help-step-number', step.number);
                var body = el('div', 'xpcalc-compare-help-step-body');
                body.appendChild(el('div', 'xpcalc-compare-help-step-title', step.title));
                body.appendChild(el('div', 'xpcalc-compare-help-step-detail', step.detail));
                row.appendChild(number);
                row.appendChild(body);
                steps.appendChild(row);
            });

            checkbox.setAttribute('data-xpcalc-skip-autosave', '1');
            checkbox.classList.add('xpcalc-compare-help-native-check');
            primary.setAttribute('data-xpcalc-skip-autosave', '1');
            secondary.setAttribute('data-xpcalc-skip-autosave', '1');
            primary.classList.add('xpcalc-button-compare-help-primary');
            secondary.classList.add('xpcalc-button-compare-help-secondary');

            note.appendChild(noteTitle);
            note.appendChild(noteCopy);
            toggleWrap.appendChild(checkbox);
            toggleWrap.appendChild(customCheck);
            toggleWrap.appendChild(toggleText);
            controls.appendChild(primary);
            controls.appendChild(secondary);

            dialog.appendChild(eyebrow);
            dialog.appendChild(title);
            dialog.appendChild(copy);
            dialog.appendChild(steps);
            dialog.appendChild(note);
            dialog.appendChild(toggleWrap);
            dialog.appendChild(controls);
            overlay.appendChild(dialog);
            overlay.hidden = true;
            document.body.appendChild(overlay);

            overlay.addEventListener('click', function (event) {
                if (event.target === overlay) {
                    comparisonHelpRememberPreference();
                    overlay.hidden = true;
                }
            });

            secondary.addEventListener('click', function () {
                comparisonHelpRememberPreference();
                overlay.hidden = true;
            });

            primary.addEventListener('click', function () {
                var startNow = comparisonHelpPendingStart;
                comparisonHelpRememberPreference();
                overlay.hidden = true;
                if (startNow) {
                    beginBuildComparison();
                }
            });

            comparisonHelpOverlay = overlay;
            comparisonHelpCheckbox = checkbox;
            comparisonHelpPrimaryButton = primary;
            comparisonHelpSecondaryButton = secondary;
            return overlay;
        }

        function openComparisonHelpModal(startAfterClose) {
            var overlay = ensureComparisonHelpModal();
            comparisonHelpPendingStart = !!startAfterClose;
            if (comparisonHelpCheckbox) {
                comparisonHelpCheckbox.checked = !comparisonHelpShouldShow();
            }
            if (comparisonHelpPrimaryButton) {
                comparisonHelpPrimaryButton.textContent = startAfterClose ? 'Start Comparison' : 'Got it';
            }
            if (comparisonHelpSecondaryButton) {
                comparisonHelpSecondaryButton.textContent = startAfterClose ? 'Cancel' : 'Close';
            }
            overlay.hidden = false;
            if (comparisonHelpPrimaryButton) {
                comparisonHelpPrimaryButton.focus();
            }
        }

        function maybeBeginBuildComparison() {
            if (comparisonHelpShouldShow()) {
                openComparisonHelpModal(true);
                return;
            }
            beginBuildComparison();
        }

        function beginBuildComparison() {
            if (buildSharedPreviewMode) {
                message.textContent = 'Save the shared build as Current or restore your own build before starting comparison.';
                return;
            }
            if (!lastCalculatedShareState) {
                message.textContent = 'Recalculate the current build before starting comparison.';
                return;
            }
            comparisonCurrentBuild = captureBuildState(root);
            comparisonCurrentResult = cloneComparisonData(lastCalculatedShareState);
            comparisonPlannedResult = cloneComparisonData(lastCalculatedShareState);
            comparisonPlannedDirty = false;
            buildComparisonMode = true;
            compare.disabled = true;
            compare.textContent = 'Comparing';
            setBuildPersistenceStatus('Autosave: Paused · Comparing');
            updateComparisonUi();
            message.textContent = 'Comparison started. Current is protected; edit Planned and press Recalculate.';
        }

        function finishBuildComparisonKeepPlanned() {
            if (!buildComparisonMode) { return; }
            if (!comparisonPlannedResult || comparisonPlannedDirty) {
                message.textContent = 'Recalculate Planned before choosing Use Planned.';
                return;
            }
            buildComparisonMode = false;
            comparisonBar.hidden = true;
            comparisonCard.card.hidden = true;
            compare.disabled = false;
            compare.textContent = 'Compare Builds';
            compare.title = 'Snapshot this calculated build as Current and create an editable Planned build.';
            comparisonCurrentBuild = null;
            comparisonCurrentResult = null;
            comparisonPlannedResult = null;
            comparisonPlannedDirty = false;
            saveBuildLocally(root);
            setBuildPersistenceStatus('Autosave: Saved');
            message.textContent = 'Planned build is now your current build and has been saved locally.';
        }

        function resetComparisonPlanned() {
            if (!buildComparisonMode || !comparisonCurrentBuild) { return; }
            showBuildLoadingModal('Resetting Planned Build', 'Restoring Planned to the protected Current baseline…');
            applyBuildState(
                root,
                comparisonCurrentBuild,
                calculateBuild,
                'Autosave: Paused · Comparing',
                function (success) {
                    if (success) {
                        comparisonPlannedDirty = false;
                        showBuildLoadingResult(true, 'Planned now matches Current again.');
                        message.textContent = 'Planned reset to Current. Make another change whenever you are ready.';
                    } else {
                        showBuildLoadingResult(false, 'Planned could not be reset completely.');
                    }
                }
            );
        }

        function exitBuildComparisonRestoreCurrent() {
            var protectedCurrent = comparisonCurrentBuild;
            if (!buildComparisonMode || !protectedCurrent) { return; }
            showBuildLoadingModal('Exiting Comparison', 'Restoring the protected Current build…');
            applyBuildState(
                root,
                protectedCurrent,
                calculateBuild,
                'Autosave: Restored',
                function (success) {
                    buildComparisonMode = false;
                    comparisonBar.hidden = true;
                    comparisonCard.card.hidden = true;
                    comparisonCurrentBuild = null;
                    comparisonCurrentResult = null;
                    comparisonPlannedResult = null;
                    comparisonPlannedDirty = false;
                    compare.disabled = !lastCalculatedShareState;
                    compare.textContent = 'Compare Builds';
                    compare.title = 'Snapshot this calculated build as Current and create an editable Planned build.';
                    if (success) {
                        saveBuildLocally(root);
                        setBuildPersistenceStatus('Autosave: Saved');
                        message.textContent = 'Comparison closed. The protected Current build has been restored.';
                        showBuildLoadingResult(true, 'Current build restored.');
                    } else {
                        showBuildLoadingResult(false, 'Current build could not be restored completely.');
                    }
                }
            );
        }

        function readActiveSynergiesForShare() {
            var counts = {};
            var result = [];

            Object.keys(TRAIT_SYNERGIES).forEach(function (key) {
                counts[key] = 0;
            });

            traitUi.forEach(function (ui) {
                if (ui.family.value && counts[ui.family.value] !== undefined) {
                    counts[ui.family.value] += 1;
                }
            });

            Object.keys(TRAIT_SYNERGIES).forEach(function (key) {
                var threshold = activeSynergyThreshold(key, counts[key]);

                if (!threshold) { return; }

                result.push({
                    key: key,
                    label: TRAIT_SYNERGIES[key].label,
                    count: counts[key],
                    text: threshold.text,
                    iconFile: TRAIT_SYNERGY_ICONS[key] || ''
                });
            });

            return result;
        }

        function selectedOptionText(select) {
            if (!select || select.selectedIndex < 0 || !select.options[select.selectedIndex]) {
                return '';
            }
            return select.options[select.selectedIndex].textContent || '';
        }

        function shareWeaponOptionLabel(statKey) {
            var label = statKey || '';
            WEAPON_OPTION_STATS.forEach(function (option) {
                if (option[0] === statKey) {
                    label = option[1];
                }
            });
            return label.replace(/\s*%$/, '');
        }

        function readTraitsForShare() {
            return traitUi.map(function (ui, index) {
                var traitKey = ui.trait.value || '';
                var def = traitKey ? TRAIT_DEFS[traitKey] : null;
                return {
                    slot: index + 1,
                    synergyKey: ui.family.value || '',
                    synergy: ui.family.value && TRAIT_SYNERGIES[ui.family.value]
                        ? TRAIT_SYNERGIES[ui.family.value].label
                        : '',
                    traitKey: traitKey,
                    trait: def ? def.label : '',
                    grade: ui.grade.value || '',
                    bonus: ui.bonus.textContent || '—'
                };
            }).filter(function (item) {
                return !!item.traitKey || !!item.synergyKey || !!item.grade;
            });
        }

        function readUpgradeGroupForShare(label, inputs, names, order, specialStars) {
            var items = [];
            (order || Object.keys(names)).forEach(function (id) {
                var input = inputs[id];
                if (!input) { return; }
                items.push({
                    id: String(id),
                    name: names[id] || ('Upgrade ' + id),
                    level: Math.max(0, Math.trunc(numberValue(input, 0)))
                });
            });
            return {
                label: label,
                stars: specialStars ? Number(specialStars.value || 1) : null,
                items: items
            };
        }

        function readUpgradeGroupsForShare() {
            return [
                readUpgradeGroupForShare('ABILITY', abilityInputs, DATA.abilityNames, ABILITY_DISPLAY_ORDER, null),
                readUpgradeGroupForShare('SOUL IMPRINT', soulInputs, DATA.soulNames, SOUL_DISPLAY_ORDER, null),
                readUpgradeGroupForShare('SPECIAL', specialInputs, DATA.specialNames, SPECIAL_DISPLAY_ORDER, specialInputs._specialStars),
                readUpgradeGroupForShare('EXTRA', extraInputs, DATA.extraNames, EXTRA_DISPLAY_ORDER, null)
            ];
        }

        function buildShareState(activeHeroName, heroStates, weapons, unit, loadout, totalPower) {
            var activeHeroState = null;
            var qualityId;
            var qualityName;

            heroStates.forEach(function (state) {
                if (state.name === activeHeroName) {
                    activeHeroState = state;
                }
            });

            if (!activeHeroState) {
                activeHeroState = {
                    name: activeHeroName,
                    level: Math.trunc(numberValue(activeHeroLevel, 1)),
                    stars: Math.trunc(numberValue(activeHeroStars, 0)),
                    qualityId: Number(activeHeroQuality.value || DATA.heroInitialQuality[activeHeroName] || 1)
                };
            }

            qualityId = Number(activeHeroState.qualityId || 1);
            qualityName = DATA.qualities[String(qualityId)] || 'Normal';

            return {
                createdAt: new Date().toISOString(),
                hero: {
                    name: activeHeroState.name,
                    level: activeHeroState.level,
                    stars: activeHeroState.stars,
                    qualityId: qualityId,
                    quality: qualityName
                },
                totalPower: Number(totalPower || 0),
                power: Number(loadout.loadoutDps || 0),
                maxHp: Number(unit.maxHp || 0),
                hpRegen: Number(unit.hpRegen || 0),
                vampRate: Number(unit.vampRate || 0),
                stats: {
                    basicAttack: Number(unit.basicAttack || 0),
                    attackSpeed: Number(unit.attackSpeed || 0),
                    doubleRate: Number(unit.doubleRate || 0),
                    tripleRate: Number(unit.tripleRate || 0),
                    critRate: Number(unit.critRate || 0),
                    critDamage: Number(unit.critDamage || 0),
                    skillDamage: Number(unit.skillDamage || 0),
                    cooldownRate: Number(unit.cooldownRate || 0),
                    melee: Number(unit.melee || 0),
                    ranged: Number(unit.ranged || 0),
                    effectResist: Number(unit.effectResist || 0),
                    move: Number(unit.move || 0)
                },
                playerLevel: Math.trunc(numberValue(playerLevel, 1)),
                heroSkill: automaticHeroSkill(activeHeroState.name, activeHeroState.stars),
                weapons: weapons.map(function (weapon) {
                    return {
                        slot: weapon.slot,
                        name: weapon.name,
                        track: weapon.track,
                        quality: weapon.quality,
                        level: weapon.level,
                        className: weapon.className,
                        options: (weapon.options || []).map(function (option) {
                            return {
                                stat: option.stat,
                                label: shareWeaponOptionLabel(option.stat),
                                value: Number(option.value || 0),
                                percent: !!PERCENT_STATS[option.stat]
                            };
                        }).filter(function (option) {
                            return !!option.stat && Number(option.value) !== 0;
                        })
                    };
                }),
                traits: readTraitsForShare(),
                upgrades: readUpgradeGroupsForShare(),
                synergies: readActiveSynergiesForShare(),
                build: captureBuildState(root)
            };
        }

        function invalidateShareBuild() {
            lastCalculatedShareState = null;
            shareBuild.disabled = true;
            shareBuild.title = 'Recalculate the build before sharing.';
        }

        function enableShareBuild(state) {
            lastCalculatedShareState = state;
            shareBuild.disabled = !state;
            shareBuild.title = state
                ? 'Create a Reddit-ready image from this calculated build.'
                : 'Recalculate the build before sharing.';
        }

