                drawSharePanel(ctx, 52, 151, 976, 154, accent, 'rgba(10,15,23,0.92)');
                if (qualityImage) {
                    ctx.save();
                    ctx.globalAlpha = 0.60;
                    drawShareNineSlice(ctx, qualityImage, 68, 168, 126, 120, SHARE_QUALITY_BORDERS[qualityName], 20);
                    ctx.restore();
                }
                if (heroImage) {
                    drawShareImageContain(ctx, heroImage, 72, 166, 118, 124, 1);
                }
                ctx.fillStyle = '#ffffff';
                ctx.font = '950 31px sans-serif';
                ctx.fillText(state.hero.name, 218, 195);
