                ctx.font = '900 18px sans-serif';
                ctx.fillText(qualityName.toUpperCase() + ' · Lv.' + state.hero.level + ' · ' + state.hero.stars + '★', 218, 226);
                ctx.fillStyle = '#b4bfce';
                ctx.font = '800 15px sans-serif';
                ctx.fillText('Player Lv.' + state.playerLevel + (state.heroSkill && state.heroSkill.label ? ' · ' + state.heroSkill.label : ''), 218, 254);

                ctx.fillStyle = '#bea2f4';
